import json

def get_structured_response(client, prompt: str) -> dict:
    response = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[{"role": "user", "content": prompt}],
        response_format={"type": "json_object"},
    )
    raw_text = response.choices[0].message.content

    try:
        data = json.loads(raw_text)
    except json.JSONDecodeError as e:
        raise ValueError(f"Model did not return valid JSON: {raw_text!r}") from e

    required_keys = {"name", "category"}
    if not required_keys.issubset(data.keys()):
        raise ValueError(f"Missing expected keys in response: {data}")

    return data

